import manifest from "@/data/r11-props.json";
import type { SiteLocale } from "@/lib/i18n/site-locales";

/**
 * OmD-made 3D props for the round-11 sample screens and example cards (owner decision 2026-10-20).
 * Generic objects generated by OmD with Codex, never brand assets. The manifest is filled by the
 * props work stream; until an id is in it, getProp returns undefined and the caller renders
 * nothing in its place (no placeholder).
 */
export const PROP_IDS = [
  "coin",
  "card",
  "check-badge",
  "parcel-box",
  "price-tag",
  "piggy-bank",
  "chart-bars",
  "receipt",
  "calculator",
  "briefcase",
  "chat-bubble",
  "palette",
  "shopping-bag",
] as const;

export type PropId = (typeof PROP_IDS)[number];

export type Prop = {
  id: PropId;
  /** public path, e.g. /r11-props/coin.webp (transparent WebP) */
  src: string;
  width: number;
  height: number;
  alt: Record<SiteLocale, string>;
  origin: "omd-generated";
  tool: string;
  created: string;
};

const PROPS = (manifest as { props: Prop[] }).props;

export function getProp(id: PropId): Prop | undefined {
  return PROPS.find((p) => p.id === id);
}
